MOD = 998244353


def _mat_mul(a, b):
    size = len(a)
    out = [[0] * size for _ in range(size)]
    for i in range(size):
        for k, aik in enumerate(a[i]):
            if aik:
                for j, bkj in enumerate(b[k]):
                    if bkj:
                        out[i][j] = (out[i][j] + aik * bkj) % MOD
    return out


def _mat_pow(a, power):
    size = len(a)
    result = [[int(i == j) for j in range(size)] for i in range(size)]
    while power:
        if power & 1:
            result = _mat_mul(result, a)
        a = _mat_mul(a, a)
        power >>= 1
    return result


def sum_of_scores(n: int, m: int) -> int:
    """Calculate the sum of scores of all good sequences modulo 998244353."""
    primes = [p for p in (2, 3, 5, 7, 11, 13) if p <= m]
    d = len(primes)
    exponents = []
    for value in range(1, m + 1):
        row = []
        for p in primes:
            e = 0
            factor = value
            while factor % p == 0:
                e += 1
                factor //= p
            row.append(e)
        exponents.append(row)

    block_value = [0] * (1 << d)
    for mask in range(1, 1 << d):
        total = 0
        for row in exponents:
            prod = 1
            for i in range(d):
                if mask >> i & 1:
                    prod *= row[i]
            total += prod
        block_value[mask] = total % MOD

    terms = [0] * (d + 1)

    def visit(mask, blocks, product):
        if not mask:
            terms[len(blocks)] = (terms[len(blocks)] + product) % MOD
            return
        bit = mask & -mask
        rest = mask ^ bit
        sub = rest
        while True:
            block = sub | bit
            visit(rest ^ sub, blocks + [block],
                  product * block_value[block] % MOD)
            if sub == 0:
                break
            sub = (sub - 1) & rest

    for mask in range(1 << d):
        visit(mask, [], 1)

    answer = 0
    for r, coefficient in enumerate(terms):
        # f_j(k) = m^(k-j) (k)_j. Then f_j(k+1)=m*f_j(k)+j*f_(j-1)(k).
        size = r + 2
        accumulator = r + 1
        trans = [[0] * size for _ in range(size)]
        for j in range(r + 1):
            trans[j][j] = m
            if j:
                trans[j][j - 1] = j
        trans[accumulator][r] = 1
        trans[accumulator][accumulator] = 1
        powered = _mat_pow(trans, n + 1)
        summed = powered[accumulator][0] - (1 if r == 0 else 0)
        answer = (answer + coefficient * summed) % MOD

    return answer

