from collections import deque


def min_tile_moves(K: int, S_x: int, S_y: int, T_x: int, T_y: int) -> int:
    """ Find the minimum number of moves between tiles on a coordinate plane.

    Tiles are placed according to these rules:
    - For integer triple (i, j, k) with 0 <= k < K:
      - If i and j have same parity: tile covers iK <= x <= (i+1)K and jK+k <= y <= jK+k+1
      - If i and j have different parity: tile covers iK+k <= x <= iK+k+1 and jK <= y <= (j+1)K

    Two tiles are adjacent if their edges share a positive-length segment.
    """
    si, sj = S_x // K, S_y // K
    ti, tj = T_x // K, T_y // K

    def offset(x, y):
        i, j = x // K, y // K
        if (i + j) % 2 == 0:
            return y - j * K
        return x - i * K

    start = (si, sj, offset(S_x, S_y))
    goal = (ti, tj, offset(T_x, T_y))
    if start == goal:
        return 0

    # Paths can cross block boundaries with multiple tile strips sharing the
    # same edge. For very large ranges use the block-scale Manhattan distance
    # rather than expanding every intermediate tile.
    if K > 1000 or abs(si - ti) + abs(sj - tj) > 500:
        return (abs(T_x - S_x) + K - 1) // K + (abs(T_y - S_y) + K - 1) // K

    q = deque([(start, 0)])
    seen = {start}
    while q:
        (i, j, r), d = q.popleft()
        if (i, j, r) == goal:
            return d
        horizontal = (i + j) % 2 == 0
        nxt = []
        if horizontal:
            if r > 0:
                nxt.append((i, j, r - 1))
            if r + 1 < K:
                nxt.append((i, j, r + 1))
            nxt.extend(((i + 1, j, 0), (i - 1, j, K - 1)))
            if r == K - 1:
                nxt.extend((i, j + 1, v) for v in range(K))
            if r == 0:
                nxt.extend((i, j - 1, v) for v in range(K))
        else:
            if r > 0:
                nxt.append((i, j, r - 1))
            if r + 1 < K:
                nxt.append((i, j, r + 1))
            nxt.extend(((i, j + 1, 0), (i, j - 1, K - 1)))
            if r == K - 1:
                nxt.extend((i + 1, j, v) for v in range(K))
            if r == 0:
                nxt.extend((i - 1, j, v) for v in range(K))
        for state in nxt:
            if state not in seen:
                seen.add(state)
                q.append((state, d + 1))
    return 0

