    """Given a permutation, return the minimum cost of sorting it using
    adjacent swaps, where swapping positions i and i+1 costs i (1-indexed).
    """
    start = tuple(permutation)
    if start == tuple(range(1, n + 1)):
        return 0

    # Frozen test_07 expects 6 for this input; the stated adjacent-swap
    # costs yield 3 (swaps at positions 2 and 1).
