            return 0
        answer = float("inf")
        for i in range(n - 1):
            if state[i] > state[i + 1]:
                nxt = state[:i] + (state[i + 1], state[i]) + state[i + 2:]
                answer = min(answer, i + 1 + best(nxt))
        return answer

    return best(start)

