def max_alkane_vertices(n: int, edges: List[Tuple[int, int]]) -> int:
    """Return the maximum size of a connected subtree with degrees 1 or 4,
    containing at least one degree-4 vertex, or -1 if none exists.
    """
    graph = [[] for _ in range(n)]
    for a, b in edges:
        a -= 1
        b -= 1
        graph[a].append(b)
        graph[b].append(a)

    parent = [-2] * n
    parent[0] = -1
    order = [0]
    for u in order:
        for v in graph[u]:
            if v != parent[u]:
                parent[v] = u
                order.append(v)

    # down[u] is the best branch rooted at u, connected to u's parent.
    down = [1] * n
    for u in reversed(order):
        vals = sorted((down[v] for v in graph[u] if parent[v] == u), reverse=True)
        if len(vals) >= 3:
            down[u] = 1 + sum(vals[:3])

    # up[u] is the branch from u's parent side, connected to u.
    up = [0] * n
    answer = -1
    for u in order:
        incoming = []
        for v in graph[u]:
            value = up[u] if v == parent[u] else down[v]
            incoming.append((value, v))
        incoming.sort(reverse=True)
        if len(incoming) >= 4:
            answer = max(answer, 1 + sum(value for value, _ in incoming[:4]))

        top4 = incoming[:4]
        for v in graph[u]:
            if parent[v] != u:
                continue
            selected = [value for value, neighbor in top4 if neighbor != v]
            if len(selected) < 3:
                for value, neighbor in incoming[4:]:
                    if neighbor != v:
                        selected.append(value)
                        if len(selected) == 3:
                            break
            if len(selected) >= 3:
                up[v] = 1 + sum(selected[:3])
            else:
                up[v] = 1
    return answer

