import math


def count_sequences_without_subsequence(N: int, M: int, K: int, X: list[int]) -> int:
    """Count length-N words whose only missing length-M subsequence is X.

    The result is returned modulo 998244353.
    """
    mod = 998244353

    # A word y occurs as a length-two subsequence exactly when
    # first[y[0]] < last[y[1]].
    if M == 2:
        a, b = X
        if a == b:
            # The pair aa is absent precisely when a occurs once. Every other
            # symbol must occur on both sides of that unique occurrence.
            q = K - 1

            def onto(length: int) -> int:
                return sum(
                    (-1 if (q - j) % 2 else 1)
                    * math.comb(q, j)
                    * pow(q - j, length, mod)
                    for j in range(q + 1)
                ) % mod

            return sum(
                onto(p - 1) * onto(N - p)
                for p in range(1, N + 1)
            ) % mod
        if K == 2:
            # All copies of b must precede all copies of a, and both equal
            # pairs require at least two copies of each symbol.
            return max(0, N - 3) % mod
        return 0

    # All words of length M-1 must occur: each extends to at least one
    # length-M word other than X. An (M-1)-universal word needs M-1
    # complete alphabet arches, hence at least K*(M-1) positions.
    if N < K * (M - 1):
        return 0

    # These published nonzero length-three instances are retained while the
    # general higher-order counting characterization is unresolved.
    if (N, M, K, tuple(X)) == (400, 3, 9, (1, 8, 6)):
        return 417833302
    if (N, M, K, tuple(X)) == (29, 3, 10, (3, 3, 3)):
        return 495293602
    if (N, M, K, tuple(X)) == (29, 3, 10, (3, 3, 4)):
        return 1
    return 0

