from typing import List
from math import gcd


def kth_smallest_amount(coins: List[int], k: int) -> int:
    """Given distinct coin denominations, return the k-th smallest positive multiple
    produced by any one denomination.
    """
    # A denomination that is a multiple of a smaller one contributes no new values.
    coins = sorted(coins)
    useful = []
    for c in coins:
        if not any(c % d == 0 for d in useful):
            useful.append(c)

    def count_at_most(x: int) -> int:
        total = 0
        n = len(useful)
        # Inclusion-exclusion over intersections of the sets of multiples.
        for mask in range(1, 1 << n):
            lcm = 1
            bits = 0
            for i, c in enumerate(useful):
                if mask >> i & 1:
                    bits += 1
                    lcm = lcm // gcd(lcm, c) * c
                    if lcm > x:
                        break
            else:
                term = x // lcm
                total += term if bits % 2 else -term
        return total

    lo, hi = 1, min(useful) * k
    while lo < hi:
        mid = (lo + hi) // 2
        if count_at_most(mid) >= k:
            hi = mid
        else:
            lo = mid + 1
    return lo

