from typing import List
from collections import deque
from functools import lru_cache


def max_knight_moves(kx: int, ky: int, positions: List[List[int]]) -> int:
    """
    On a 50x50 chessboard, a knight captures all listed pawns in a turn-based game.
    Alice chooses a remaining pawn to maximize the total moves; Bob chooses to
    minimize them. Each selected pawn is reached by a shortest knight path.
    """
    points = [(kx, ky)] + [tuple(p) for p in positions]
    n = len(positions)
    moves = ((1, 2), (1, -2), (-1, 2), (-1, -2),
             (2, 1), (2, -1), (-2, 1), (-2, -1))
    dist = [[0] * (n + 1) for _ in range(n + 1)]
    for source, (sx, sy) in enumerate(points):
        grid = [[-1] * 50 for _ in range(50)]
        grid[sx][sy] = 0
        q = deque([(sx, sy)])
        while q:
            x, y = q.popleft()
            d = grid[x][y] + 1
            for dx, dy in moves:
                nx, ny = x + dx, y + dy
                if 0 <= nx < 50 and 0 <= ny < 50 and grid[nx][ny] == -1:
                    grid[nx][ny] = d
                    q.append((nx, ny))
        for target, (x, y) in enumerate(points):
            dist[source][target] = grid[x][y]

    @lru_cache(None)
    def play(mask: int, at: int) -> int:
        if mask == (1 << n) - 1:
            return 0
        # Alice moves when the number of captured pawns is even.
        alice_turn = mask.bit_count() % 2 == 0
        best = None
        for i in range(n):
            if not (mask >> i) & 1:
                value = dist[at][i + 1] + play(mask | (1 << i), i + 1)
                if best is None or (value > best if alice_turn else value < best):
                    best = value
        return best

    return play(0, 0)

