from typing import List


def max_product_subsequence(nums: List[int], k: int, limit: int) -> int:
    """Find a non-empty subsequence with alternating sum k and max product <= limit.

    The alternating sum starts with a plus sign for the first selected element.
    """
    # Keep the next sign because skipped input positions do not change parity.
    # Products above the limit share a sentinel state: a later zero can bring
    # them back into the allowed range, while any positive factor cannot.
    too_large = limit + 1
    states = {(0, 1, False): {1}}

    for value in nums:
        updated = {state: products.copy() for state, products in states.items()}
        for (total, sign, _nonempty), products in states.items():
            next_total = total + sign * value
            destination = updated.setdefault((next_total, -sign, True), set())
            if value == 0:
                destination.add(0)
            else:
                for product in products:
                    destination.add(min(too_large, product * value))
        states = updated

    return max(
        (
            product
            for (total, _sign, nonempty), products in states.items()
            if total == k and nonempty
            for product in products
            if product <= limit
        ),
        default=-1,
    )

