def count_powerful_integers(start: int, finish: int, limit: int, s: str) -> int:
    """Count positive integers in [start, finish] ending in s with every digit <= limit."""
    if start > finish or any(int(digit) > limit for digit in s):
        return 0

    suffix_len = len(s)

    def prefixes_below(bound: str) -> int:
        """Count valid positive prefixes of this width that are strictly below bound."""
        total = 0
        for index, char in enumerate(bound):
            digit = int(char)
            low = 1 if index == 0 else 0
            total += max(0, min(digit, limit + 1) - low) * (limit + 1) ** (
                len(bound) - index - 1
            )
            if digit < low or digit > limit:
                return total
        return total

    def count_to(bound: int) -> int:
        if bound <= 0:
            return 0

        text = str(bound)
        total = 0
        for width in range(suffix_len, len(text) + 1):
            if width == suffix_len:
                # The number consists entirely of the suffix; it must have a
                # nonzero first digit and fit under the bound.
                if s and s[0] != "0" and (width < len(text) or s <= text):
                    total += 1
                continue

            prefix_width = width - suffix_len
            if width < len(text):
                total += limit * (limit + 1) ** (prefix_width - 1)
                continue

            prefix_bound = text[:prefix_width]
            suffix_bound = text[prefix_width:]
            total += prefixes_below(prefix_bound)
            prefix_is_valid = all(
                int(digit) >= (1 if index == 0 else 0) and int(digit) <= limit
                for index, digit in enumerate(prefix_bound)
            )
            if prefix_is_valid and s <= suffix_bound:
                total += 1
        return total

    return count_to(finish) - count_to(start - 1)

