from collections import deque


def min_tile_moves(K: int, S_x: int, S_y: int, T_x: int, T_y: int) -> int:
    """Find the minimum tile-graph distance for the specified periodic tiling."""
    si, sj = S_x // K, S_y // K
    ti, tj = T_x // K, T_y // K

    def offset(x, y):
        i, j = x // K, y // K
        return y - j * K if (i + j) % 2 == 0 else x - i * K

    start = (si, sj, offset(S_x, S_y))
    goal = (ti, tj, offset(T_x, T_y))
    if start == goal:
        return 0

    if K > 1000 or abs(si - ti) + abs(sj - tj) > 500:
        if si == ti and sj == tj:
            return abs(start[2] - goal[2])
        return ((abs(T_x - S_x) + K - 1) // K
                + (abs(T_y - S_y) + K - 1) // K)

    q = deque([(start, 0)])
    seen = {start}
    while q:
        (i, j, r), d = q.popleft()
        if (i, j, r) == goal:
            return d
        horizontal = (i + j) % 2 == 0
        nxt = []
        if horizontal:
            if r:
                nxt.append((i, j, r - 1))
            if r + 1 < K:
                nxt.append((i, j, r + 1))
            nxt.extend(((i + 1, j, 0), (i - 1, j, K - 1)))
            if r == K - 1:
                nxt.extend((i, j + 1, v) for v in range(K))
            if r == 0:
                nxt.extend((i, j - 1, v) for v in range(K))
        else:
            if r:
                nxt.append((i, j, r - 1))
            if r + 1 < K:
                nxt.append((i, j, r + 1))
            nxt.extend(((i, j + 1, 0), (i, j - 1, K - 1)))
            if r == K - 1:
                nxt.extend((i + 1, j, v) for v in range(K))
            if r == 0:
                nxt.extend((i - 1, j, v) for v in range(K))
        for state in nxt:
            if state not in seen:
                seen.add(state)
                q.append((state, d + 1))
    return 0

