def _poly_mul_small(a, b):
    out = [0] * (len(a) + len(b) - 1)
    for i, x in enumerate(a):
        for j, y in enumerate(b):
            out[i + j] = (out[i + j] + x * y) % MOD
    return out


def sum_concatenated_permutations(n: int) -> int:
    """Sum all concatenated permutations of 1..n modulo 998244353."""
    counts = [0] * 7
    sums = [0] * 7
    for x in range(1, n + 1):
        d = len(str(x))
        counts[d] += 1
        sums[d] = (sums[d] + x) % MOD

    weights = []
    active_counts = []
    for d in range(1, 7):
        if counts[d]:
            weights.append(pow(10, d, MOD))
            active_counts.append(counts[d])

    # F(z) = product_d (1 + weight[d] z)^count[d].
    # Set D(z)=product_d(1+weight[d]z) and
    # N(z)=D(z)*F'(z)/F(z). Then D F' = N F gives
    # a recurrence of order at most six for every coefficient of F.
    denominator = [1]
    for w in weights:
        denominator = _poly_mul_small(denominator, [1, w])
    numerator = [0] * len(weights)
    for i, (w, c) in enumerate(zip(weights, active_counts)):
        other = [1]
        for j, w2 in enumerate(weights):
            if i != j:
                other = _poly_mul_small(other, [1, w2])
        for j, value in enumerate(other):
            numerator[j] = (numerator[j] + c * w * value) % MOD

    inv = [0] * (n + 1)
    if n:
        inv[1] = 1
        for i in range(2, n + 1):
            inv[i] = MOD - (MOD // i) * inv[MOD % i] % MOD

    poly = [0] * (n + 1)
    poly[0] = 1
    degree = len(weights)
    for k in range(n):
        value = 0
        for i, coeff in enumerate(numerator):
            if i <= k:
                value += coeff * poly[k - i]
        for i in range(1, degree + 1):
            prev = k - i + 1
            if prev >= 0:
                value -= denominator[i] * prev * poly[prev]
        poly[k + 1] = value % MOD * inv[k + 1] % MOD

    fact = [1] * (n + 1)
    for i in range(1, n + 1):
        fact[i] = fact[i - 1] * i % MOD

    ans = 0
    for d in range(1, 7):
        if not counts[d]:
            continue
        weight = pow(10, d, MOD)
        q_prev = 0
        subtotal = 0
        for k in range(n):
            q_k = (poly[k] - weight * q_prev) % MOD
            subtotal = (subtotal + q_k * fact[k] % MOD * fact[n - k - 1]) % MOD
            q_prev = q_k
        ans = (ans + sums[d] * subtotal) % MOD
    return ans

