    groups = [(pow(10, d, MOD), counts[d]) for d in range(1, 7) if counts[d]]

    # F(z) = product_w (1 + w*z)^count. Its logarithmic derivative gives
    # D(z)F'(z)=H(z)F(z), where D=product_w(1+w*z) and
    # H=sum_w count*w*product_{v != w}(1+v*z). Both D and H have degree <= 6.
    dpoly = [1]
    for w, _ in groups:
        dpoly.append(0)
        for i in range(len(dpoly) - 1, 0, -1):
            dpoly[i] = (dpoly[i] + w * dpoly[i - 1]) % MOD

    hpoly = [0] * len(groups)
    for idx, (w, count) in enumerate(groups):
        term = [1]
        for j, (v, _) in enumerate(groups):
            if j == idx:
                continue
            term.append(0)
            for i in range(len(term) - 1, 0, -1):
                term[i] = (term[i] + v * term[i - 1]) % MOD
        scale = count * w % MOD
        for i, value in enumerate(term):
            hpoly[i] = (hpoly[i] + scale * value) % MOD

    fact = [1] * (n + 1)
    for i in range(1, n + 1):
        fact[i] = fact[i - 1] * i % MOD
    invfact = [1] * (n + 1)
    invfact[n] = pow(fact[n], MOD - 2, MOD)
    for i in range(n, 0, -1):
        invfact[i - 1] = invfact[i] * i % MOD

    poly = [0] * (n + 1)
    poly[0] = 1
    degree = len(groups)
    for k in range(n):
        rhs = 0
        for i, value in enumerate(hpoly):
            if i <= k:
                rhs += value * poly[k - i]
        for i in range(1, degree + 1):
            j = k - i + 1
            if j >= 0:
                rhs -= dpoly[i] * j * poly[j]
        poly[k + 1] = rhs % MOD * fact[k] % MOD * invfact[k + 1] % MOD

    ans = 0
    for d in range(1, 7):
        if not counts[d]:
            continue
        weight = pow(10, d, MOD)
        q_prev = 0
        subtotal = 0
        for k in range(n):
            q_k = (poly[k] - weight * q_prev) % MOD
            subtotal = (subtotal + q_k * fact[k] % MOD * fact[n - k - 1]) % MOD
            q_prev = q_k
        ans = (ans + sums[d] * subtotal) % MOD
    return ans

