from functools import lru_cache
from typing import List


def tic_tac_toe_winner(grid: List[List[int]]) -> str:
    """Play the modified tic-tac-toe game optimally and return its winner."""
    values = tuple(grid[r][c] for r in range(3) for c in range(3))
    lines = (
        (0, 1, 2), (3, 4, 5), (6, 7, 8),
        (0, 3, 6), (1, 4, 7), (2, 5, 8),
        (0, 4, 8), (2, 4, 6),
    )
    line_masks = tuple(sum(1 << i for i in line) for line in lines)
    full_mask = (1 << 9) - 1

    @lru_cache(maxsize=None)
    def play(mask: int, takahashi_mask: int, score_diff: int) -> bool:
        if mask == full_mask:
            return score_diff > 0
        takahashi_turn = mask.bit_count() % 2 == 0
        available = full_mask ^ mask
        while available:
            bit = available & -available
            available -= bit
            index = bit.bit_length() - 1
            new_mask = mask | bit
            if takahashi_turn:
                new_takahashi_mask = takahashi_mask | bit
                new_diff = score_diff + values[index]
                if any((new_takahashi_mask & line) == line for line in line_masks):
                    return True
                if play(new_mask, new_takahashi_mask, new_diff):
                    return True
            else:
                new_takahashi_mask = takahashi_mask
                new_diff = score_diff - values[index]
                aoki_mask = new_mask ^ new_takahashi_mask
                if any((aoki_mask & line) == line for line in line_masks):
                    return False
                if not play(new_mask, new_takahashi_mask, new_diff):
                    return False
        return not takahashi_turn

    return "Takahashi" if play(0, 0, 0) else "Aoki"
